from typing import List

def sort_numbers(numbers: str) -> str:
    """ Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sort_numbers('three one five')
    'one three five'
    """
    # Mapping from string representation to integer
    number_map = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Split the input string into a list of strings
    number_strings = numbers.split()

    # Convert the list of strings to a list of integers
    numbers = [number_map[n] for n in number_strings]

    # Sort the list of integers
    numbers.sort()

    # Convert the sorted list of integers back to a list of strings
    sorted_numbers = [str(num) for num in numbers]

    # Join the list of strings back into a single string
    sorted_numbers_string = ' '.join(sorted_numbers)

    return sorted_numbers_string
```

